%% test_plot_focus.m
% Script to compare plot(ax, ...) vs plot(...) regarding figure focus
% NOTE: autogenerated by ChatGPT, modified by PeterC

clear; clc;

%% Test 1: Explicit axes handle -> plot(objAxExplicit, ...)
objFigExplicit = figure('Name','Explicit axes test');
objAxExplicit = axes('Parent', objFigExplicit);
title(objAxExplicit, 'Explicit: plot(ax, ...)');

disp('==============================');
disp('TEST 1: plot(ax, ...)');
disp('==============================');
disp('1) Make sure this figure is created.');
disp('2) Click back on the Command Window or Editor so MATLAB GUI has focus there.');
disp('3) Press Enter to start the test and watch whether the figure steals focus.');
input('   Press Enter to start TEST 1...','s');

for ui32K = 1:300
    dX = linspace(0, 2*pi, 200);
    dY = sin(dX + 0.1 * double(ui32K));

    % Explicit axes: should NOT bring the figure to the foreground
    plot(objAxExplicit, dX, dY);

    % drawnow limitrate;    % minimal GUI update
    pause(0.005);          % slow down so you can see behavior
end

disp('TEST 1 done. The figure should NOT have repeatedly stolen focus.');

%% Test 2: Implicit current axes -> plot(...)
objFigImplicit = figure('Name','Implicit axes test');
objAxImplicit = axes('Parent', objFigImplicit);
title(objAxImplicit, 'Implicit: plot(...)');

% Make objAxImplicit the current axes once
axes(objAxImplicit);  %#ok<LAXES> % sets gca for the following plot(...) calls

disp(' ');
disp('==============================');
disp('TEST 2: plot(...) (implicit current axes)');
disp('==============================');
disp('1) Make sure this second figure is created.');
disp('2) Click back on the Command Window or Editor so MATLAB GUI has focus there.');
disp('3) Press Enter to start the test and watch whether the figure steals focus.');
input('   Press Enter to start TEST 2...','s');

for ui32K = 1:300
    dX = linspace(0, 2*pi, 200);
    dY = cos(dX + 0.1 * double(ui32K));

    % Implicit axes: this may bring the figure to the foreground on updates
    plot(dX, dY);

    % drawnow;              % full GUI update, more likely to trigger focus issues
    pause(0.05);
end

disp('TEST 2 done. Compare how often the second figure grabbed focus vs the first.');
